/// A brand mark scaled to fit its rect, centred.
struct BrandMarkShape: Shape {
    let mark: BrandMark

    func path(in rect: CGRect) -> Path {
        guard let segments = SVGPath.parse(mark.pathData) else { return Path() }
        var p = Path()
        for segment in segments {
            switch segment {
            case .move(let to): p.move(to: to)
            case .line(let to): p.addLine(to: to)
            case .cubic(let c1, let c2, let to): p.addCurve(to: to, control1: c1, control2: c2)
            case .quad(let c, let to): p.addQuadCurve(to: to, control: c)
            case .close: p.closeSubpath()
            }
        }
        let side = min(rect.width, rect.height)
        let scale = side / 24
        let transform = CGAffineTransform(translationX: rect.midX - side / 2, y: rect.midY - side / 2).scaledBy(x: scale, y: scale)
        return p.applying(transform)
    }
}
